    {
      printf("wifi_test: SDIO not ready\n");
      return 1;
    }

  printf("wifi_test: SDIO ready funcs=%u rca=0x%04x\n",
         result.function_count, result.rca);

  for (fn = 0; fn <= result.function_count; fn++)
    {
      ret = wifi_test_dump_cis((uint8_t)fn);
      if (ret < 0)
        {
          return 1;
        }
    }

  return 0;
}

