                                sdio_eventset_t eventset, uint32_t timeout) {
  AIC_SDIO_LOG_ARGS("dev=%p eventset=0x%08" PRIx32 " timeout=%" PRIu32, dev,
                    (uint32_t)eventset, timeout);
