                while (ret || (intstatus & SDIO_OTHER_INTERRUPT)) {
                    AIC_LOG_PRINTF("ret=%d, intstatus=%x\n",ret, intstatus);
                     ret = aicwf_sdio_readb(sdiodev, sdiodev->sdio_reg.block_cnt_reg, &intstatus);
                    retry_cnt++;
                    if (retry_cnt >= 8) {
                        break;
                    }
