static FAR const char *wifi_test_tuple_name(uint8_t code)
{
  switch (code)
    {
      case 0x01:
        return "DEVICE";
      case 0x15:
        return "VERS_1";
      case 0x20:
        return "MANFID";
      case 0x21:
        return "FUNCID";
      case 0x22:
        return "FUNCE";
      default:
        return "UNKNOWN";
    }
}

