  ret = wifi_test_mm_stackstart(false, true);
  if (ret < 0)
    {
      return 1;
    }

  usleep(WIFI_TEST_POST_STACK_DELAY_US);

  ret = wifi_test_mm_rfcalib(false, true);
  if (ret < 0)
    {
      return 1;
    }

  printf("wifi_test: rf chain ok\n");
