static void wifi_test_dump_rx_packet(FAR const uint8_t *rx,
                                     unsigned int rx_len)
{
  unsigned int sdio_len;
  uint8_t crc;
  uint8_t type;

  if (rx_len < WIFI_TEST_AIC_TX_HDR_LEN)
    {
      printf("wifi_test: rx packet too short: %u\n", rx_len);
      return;
    }

  sdio_len = (unsigned int)rx[0] | (((unsigned int)rx[1] & 0x0f) << 8);
  type = rx[2];
  crc = wifi_test_crc8(rx, 3);

  printf("wifi_test: rx sdio_len=%u host_type=0x%02x(%s) crc=0x%02x/%s "
         "total=%u\n",
         sdio_len, type, wifi_test_host_type_name(type), rx[3],
         crc == rx[3] ? "ok" : "bad", rx_len);

  if ((type == WIFI_TEST_AIC_MSG_TYPE || type == WIFI_TEST_AIC_CFG_TYPE ||
       type == WIFI_TEST_AIC_CFG_DATA_CFM) &&
      rx_len >= WIFI_TEST_AIC_TX_HDR_LEN + WIFI_TEST_AIC_E2A_HDR_LEN)
    {
      printf("  msg id=0x%04x dest=0x%04x src=0x%04x param_len=%u "
             "pattern=0x%08lx\n",
             wifi_test_get_le16(&rx[4]),
             wifi_test_get_le16(&rx[6]),
             wifi_test_get_le16(&rx[8]),
             wifi_test_get_le16(&rx[10]),
             (unsigned long)wifi_test_get_le32(&rx[12]));
    }

  wifi_test_hexdump(rx, rx_len > 96 ? 96 : rx_len);
}

static int wifi_test_rxpoll(unsigned int count)
{
  static uint8_t rx[WIFI_TEST_AIC_MSG_MAX_SIZE];
  unsigned int rx_len;
  unsigned int i;
  int ret;

  ret = wifi_test_enable();
  if (ret != 0)
    {
      return ret;
    }

  for (i = 0; i < count; i++)
    {
      memset(rx, 0, sizeof(rx));
      rx_len = 0;

      ret = wifi_test_msg_recv(rx, sizeof(rx), &rx_len, true, 1);
      if (ret == -ETIMEDOUT)
        {
          printf("wifi_test: rxpoll[%u] no packet\n", i);
          usleep(100 * 1000);
          continue;
        }

      if (ret < 0)
        {
          printf("wifi_test: rxpoll[%u] failed: %s (%d)\n",
                 i, strerror(-ret), ret);
          return 1;
        }

      printf("wifi_test: rxpoll[%u]\n", i);
      wifi_test_dump_rx_packet(rx, rx_len);
    }

  return 0;
}

