-
-      if (link > WIFI_TEST_CIS_MAX_TUPLE_DATA)
-        {
-          printf(" ...");
-        }
-
-      printf("\n");
-
-      if (code == 0x20 && link >= 4)
-        {
-          printf("    manf=0x%04x card=0x%04x\n",
