static void wifi_test_put_le32(FAR uint8_t *buffer, uint32_t value)
{
  buffer[0] = (uint8_t)(value & 0xff);
  buffer[1] = (uint8_t)((value >> 8) & 0xff);
  buffer[2] = (uint8_t)((value >> 16) & 0xff);
  buffer[3] = (uint8_t)(value >> 24);
}

