static int wifi_test_rxpoll(unsigned int count)
{
  FAR uint8_t *rx;
  size_t rx_size;
  unsigned int rx_len;
  unsigned int i;
  int ret;

  ret = wifi_test_enable();
  if (ret != 0)
    {
      return ret;
    }

  rx = wifi_test_rx_alloc(&rx_size);
  for (i = 0; i < count; i++)
    {
      memset(rx, 0, rx_size);
      rx_len = 0;

      ret = wifi_test_msg_recv(rx, rx_size, &rx_len, true, 1);
      if (ret == -ETIMEDOUT)
        {
          printf("wifi_test: rxpoll[%u] no packet\n", i);
          usleep(100 * 1000);
          continue;
        }

      if (ret < 0)
        {
          printf("wifi_test: rxpoll[%u] failed: %s (%d)\n",
                 i, strerror(-ret), ret);
          wifi_test_rx_free(rx);
          return 1;
        }

      printf("wifi_test: rxpoll[%u]\n", i);
      wifi_test_dump_rx_packet(rx, rx_len);
    }

  wifi_test_rx_free(rx);
  return 0;
}

