      arg |= (1ul << 27) | nblocks;
    }

  if (write)
    {
      arg |= 1ul << 31;
    }

  if (inc_addr)
    {
      arg |= 1ul << 26;
    }

  cmd = write ? SDIO_CMD53WR : SDIO_CMD53RD;

  SDIO_BLOCKSETUP(g_sdmc0, blocklen, nblocks == 0 ? 1 : nblocks);
