static uint16_t wifi_test_scan_freq_from_arg(FAR const char *arg)
{
  unsigned long channel;

  if (arg == NULL)
    {
      return 2437;
    }

  channel = strtoul(arg, NULL, 0);
  switch (channel)
    {
      case 1:
        return 2412;
      case 6:
        return 2437;
      case 11:
        return 2462;
      default:
        return (uint16_t)channel;
    }
}

