        }

      NETDEV_TXDONE(priv->dev);
      priv->txtail = (priv->txtail + 1) % D13X_GMAC_TX_COUNT;
      priv->txpending--;
    }

  if (priv->txpending < D13X_GMAC_TX_COUNT)
    {
      devif_poll(&priv->dev, d13x_gmac_txpoll);
    }
}

