}

static FAR const uint8_t *wifi_test_80211_sa(FAR const uint8_t *frame)
{
  uint16_t fctl = wifi_test_get_le16(frame);

  if ((fctl & WIFI_TEST_80211_FCTL_FROMDS) != 0)
    {
