static uint8_t wifi_test_crc8(FAR const uint8_t *buffer, uint16_t length)
{
  uint8_t crc = 0;
  uint8_t mask;

  while (length-- > 0)
    {
      for (mask = 0x80; mask != 0; mask >>= 1)
        {
          if ((crc & 0x80) != 0)
            {
              crc <<= 1;
              crc ^= 0x07;
            }
          else
            {
              crc <<= 1;
            }

          if ((*buffer & mask) != 0)
            {
              crc ^= 0x07;
            }
        }

      buffer++;
    }

  return crc;
}

static void wifi_test_put_le16(FAR uint8_t *buffer, uint16_t value)
{
