  priv->txavail_count++;
  if (priv->txavail_count <= 8 || (priv->txavail_count % 32) == 0)
    {
      printf("wifi_test: %s txavail count=%u ifup=%s connected=%s\n",
             dev->d_ifname, priv->txavail_count,
             priv->ifup ? "yes" : "no",
             priv->connected ? "yes" : "no");
    }

  devif_poll(dev, wifi_test_net_txpoll);
  return 0;
}

