{
  FAR struct wifi_test_netdev_s *priv = &g_wifi_test_netdev;
  int ret;

  if (priv->registered)
    {
      printf("wifi_test: %s already registered\n", priv->dev.d_ifname);
      return 0;
    }

  memset(priv, 0, sizeof(*priv));
