int netdev_ifup(FAR struct net_driver_s *dev)
{
  int ret = -ENOSYS;

  /* Make sure that the device supports the d_ifup() method */

  if (dev->d_ifup != NULL)
    {
      /* Is the interface already up? */

      if ((dev->d_flags & IFF_UP) == 0)
