                                priv->freq_set ? priv->freq : 0xffff);
}

static int wifi_test_net_ioctl(FAR struct net_driver_s *dev, int cmd,
                               unsigned long arg)
{
  FAR struct wifi_test_netdev_s *priv = dev->d_private;
