        if (len > 0 && iwr->u.essid.pointer != NULL)
          {
            memcpy(priv->ssid, iwr->u.essid.pointer, len);
          }

        priv->want_connect = iwr->u.essid.flags != IW_ESSID_OFF;
        if (!priv->want_connect)
