static void wifi_test_rx_thread_stop(void)
{
  FAR struct wifi_test_netdev_s *priv = &g_wifi_test_netdev;
  int i;

  if (!priv->rx_running)
    {
      priv->rx_stop = true;
      priv->rx_pid = -1;
      return;
    }

  priv->rx_stop = true;
  for (i = 0; i < 50 && priv->rx_running; i++)
    {
      usleep(WIFI_TEST_RX_THREAD_SLEEP_US);
    }
}

