static unsigned int wifi_test_align_block(unsigned int length)
{
  return ((length + WIFI_TEST_AIC_BLOCK_SIZE - 1) /
          WIFI_TEST_AIC_BLOCK_SIZE) * WIFI_TEST_AIC_BLOCK_SIZE;
