  ret = wifi_test_auto_init(false);
  if (ret != 0)
    {
      return ret < 0 ? 1 : ret;
    }

  if (priv->connected)
    {
      printf("wifi_test: %s already connected\n", priv->dev.d_ifname);
      netdev_carrier_on(&priv->dev);
      ret = wifi_test_rx_thread_start();
      return ret < 0 ? 1 : 0;
    }

  if (priv->vif_added)
    {
      vif_idx = priv->vif_idx;
