#ifdef CONFIG_BOARD_COREDUMP_BLKDEV
#  define MMCSD_USLEEP(usec) \
    do \
    { \
      if (up_interrupt_context()) \
        { \
          up_udelay(usec); \
        } \
      else \
        { \
