static uint64_t recorder_milliseconds(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u;
}

static uint16_t recorder_le16(FAR const uint8_t *buffer)
{
  return (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
}

static uint32_t recorder_le32(FAR const uint8_t *buffer)
{
  return (uint32_t)buffer[0] | ((uint32_t)buffer[1] << 8) |
         ((uint32_t)buffer[2] << 16) | ((uint32_t)buffer[3] << 24);
}

static int recorder_read_exact(int fd, FAR uint8_t *buffer, size_t length)
{
  size_t done = 0;

  while (done < length)
    {
      ssize_t received = read(fd, buffer + done, length - done);

      if (received < 0)
        {
          return -errno;
        }

      if (received == 0)
        {
          return -ENODATA;
        }

      done += received;
    }

  return OK;
}

static int recorder_mount_sd(void)
{
  struct statfs filesystem;
  int ret;

  if (statfs(RECORDER_SD_MOUNTPOINT, &filesystem) == 0)
    {
      return OK;
    }

  if (mkdir(RECORDER_SD_MOUNTPOINT, 0777) < 0 && errno != EEXIST)
    {
      return -errno;
    }

  ret = d13x_sdmc1_reprobe();
  if (ret < 0)
    {
      return ret;
    }

  ret = mount(RECORDER_SD_DEVICE, RECORDER_SD_MOUNTPOINT, "fatfs",
              MS_NOSUID | MS_SYNCHRONOUS, NULL);
  if (ret < 0 && errno != EBUSY)
    {
      return -errno;
    }

  return OK;
}

static int recorder_next_path(FAR char *path, size_t length)
{
  struct stat st;
  unsigned int index;
  int ret;

  for (index = 1; index <= 999; index++)
    {
      ret = snprintf(path, length, "%s%03u.wav",
                     RECORDER_FILE_PREFIX, index);
      if (ret < 0 || ret >= (int)length)
        {
          return -ENAMETOOLONG;
        }

      if (stat(path, &st) < 0)
        {
          return errno == ENOENT ? OK : -errno;
        }
    }

  return -ENOSPC;
}

