}

static int recorder_read_exact(int fd, FAR uint8_t *buffer, size_t length)
{
  size_t done = 0;

  while (done < length)
    {
      ssize_t received = read(fd, buffer + done, length - done);

      if (received < 0)
        {
          return -errno;
        }

      if (received == 0)
        {
          return -ENODATA;
        }

      done += received;
    }

  return OK;
}

static void recorder_partition_handler(FAR struct partition_s *part,
