int d13x_sdmc1_initialize(void)
{
  int ret;

  if (g_sdmc1 != NULL)
    {
      return OK;
    }

  g_sdmc1 = sdio_initialize(D13X_SDMC1_SLOT);
  if (g_sdmc1 == NULL)
    {
      return -ENODEV;
    }

  /* The first milestone requires a card to be inserted at boot and does not
   * start the shared hotplug polling worker.
   */

  sdio_mediachange(g_sdmc1, true);
  ret = mmcsd_slotinitialize(D13X_SDMC1_MINOR, g_sdmc1);
  if (ret < 0)
    {
      g_sdmc1 = NULL;
      return ret;
    }

  return OK;
}

int d13x_sdmc1_reprobe(void)
{
  FAR struct inode *inode;
  int i;
  int ret;

  ret = find_blockdriver("/dev/mmcsd0", 0, &inode);
  if (ret >= 0)
    {
      close_blockdriver(inode);
      return OK;
    }

  ret = d13x_sdmc1_initialize();
  if (ret < 0)
    {
      return ret;
    }

  for (i = 0; i < D13X_SDMC1_REPROBE_RETRIES; i++)
    {
      SDIO_RESET(g_sdmc1);
      sdio_mediachange(g_sdmc1, false);
      up_mdelay(D13X_SDMC1_REPROBE_DELAY_MS);
      sdio_mediachange(g_sdmc1, true);

      ret = find_blockdriver("/dev/mmcsd0", 0, &inode);
      if (ret >= 0)
        {
          close_blockdriver(inode);
          syslog(LOG_INFO, "[D13X] SDMC1 reprobe registered /dev/mmcsd0\n");
          return OK;
        }
    }

  syslog(LOG_ERR, "[D13X] SDMC1 reprobe failed: %d\n", ret);
  return ret;
}

