+int d13x_sdmc0_wifi_power(bool enable)
+{
+  unsigned int group;
+  unsigned int pin;
+  int ret;
+
+  ret = d13x_sdmc0_wifi_gpio(&group, &pin);
+  if (ret < 0)
+    {
+      return ret;
