+  sdio_mediachange(g_sdmc0, true);
+  SDIO_RESET(g_sdmc0);
+  SDIO_CLOCK(g_sdmc0, CLOCK_IDMODE);
+  g_sdmc0_wifi_ready = false;
+  g_sdmc0_wifi_selected = false;
+  g_sdmc0_wifi_ocr = 0;
+  g_sdmc0_wifi_rca = 0;
