+  g_sdmc0_wifi_memory = false;
+
+  ret = d13x_sdmc0_wifi_sendcmd(g_sdmc0, MMCSD_CMD0, 0);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  up_mdelay(2);
+
+  ret = d13x_sdmc0_wifi_sendcmd(g_sdmc0, SDIO_CMD5, 0);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  ret = SDIO_RECVR4(g_sdmc0, SDIO_CMD5, &ocr);
+  if (ret < 0)
+    {
+      return ret;
+    }
