/****************************************************************************
 * Name: nxrecorder_write_common
 *
 *   Performs common function to write data to apb buffer
 *
 * Input Parameters:
 *   fd     - recording file descriptor
 *   apb    - ap buffer
 *
 * Returned Value:
 *   OK if apb buffer write successfully.
 *
 ****************************************************************************/

int nxrecorder_write_common(int fd, FAR struct ap_buffer_s *apb)
{
  int ret = 0;

  ret = write(fd, apb->samp, apb->nbytes);
  if (ret < 0)
    {
      auderr("ERROR: precorder write failed: %d\n", ret);
    }

  return ret;
}

static void nxrecorder_put_le16(FAR uint8_t *buffer, uint16_t value)
{
  buffer[0] = value & 0xff;
  buffer[1] = value >> 8;
}

static void nxrecorder_put_le32(FAR uint8_t *buffer, uint32_t value)
{
  buffer[0] = value & 0xff;
  buffer[1] = (value >> 8) & 0xff;
  buffer[2] = (value >> 16) & 0xff;
  buffer[3] = value >> 24;
}

static int nxrecorder_write_exact(int fd, FAR const uint8_t *buffer,
                                  size_t length)
{
  size_t done = 0;

  while (done < length)
    {
      ssize_t written = write(fd, buffer + done, length - done);

      if (written <= 0)
        {
          return -EIO;
        }

      done += written;
    }

  return OK;
}

int nxrecorder_write_wav(int fd, uint32_t samplerate,
                         uint8_t chans, uint8_t bps)
{
  uint8_t header[44];
  uint32_t byterate;
  uint16_t align;

  if (chans == 0 || bps != 16 || samplerate == 0)
    {
      return -EINVAL;
    }

  byterate = samplerate * chans * (bps / 8);
  align = chans * (bps / 8);
  memset(header, 0, sizeof(header));
  memcpy(&header[0], "RIFF", 4);
  nxrecorder_put_le32(&header[4], 36);
  memcpy(&header[8], "WAVEfmt ", 8);
  nxrecorder_put_le32(&header[16], 16);
  nxrecorder_put_le16(&header[20], 1);
  nxrecorder_put_le16(&header[22], chans);
  nxrecorder_put_le32(&header[24], samplerate);
  nxrecorder_put_le32(&header[28], byterate);
  nxrecorder_put_le16(&header[32], align);
  nxrecorder_put_le16(&header[34], bps);
  memcpy(&header[36], "data", 4);
  return nxrecorder_write_exact(fd, header, sizeof(header));
}

int nxrecorder_finalize_wav(int fd)
{
  uint8_t value[4];
  off_t end;
  uint32_t data_bytes;

  end = lseek(fd, 0, SEEK_END);
  if (end < 44 || (uint64_t)end - 44 > UINT32_MAX)
    {
      return -EINVAL;
    }

  data_bytes = end - 44;
  nxrecorder_put_le32(value, 36 + data_bytes);
  if (lseek(fd, 4, SEEK_SET) < 0 ||
      nxrecorder_write_exact(fd, value, sizeof(value)) < 0)
    {
      return -EIO;
    }

  nxrecorder_put_le32(value, data_bytes);
  if (lseek(fd, 40, SEEK_SET) < 0 ||
      nxrecorder_write_exact(fd, value, sizeof(value)) < 0)
    {
      return -EIO;
    }

  fsync(fd);
  return OK;
}

