+static void nxrecorder_put_le32(FAR uint8_t *buffer, uint32_t value)
+{
+  buffer[0] = value & 0xff;
+  buffer[1] = (value >> 8) & 0xff;
+  buffer[2] = (value >> 16) & 0xff;
+  buffer[3] = value >> 24;
