static int aic_audio_cpu_thread(int argc, FAR char *argv[]) {
  struct aic_audio_s *priv = &g_aic_audio;
  int ret;

  UNUSED(argc);
  UNUSED(argv);

  for (;;) {
    nxsem_wait_uninterruptible(&priv->cpu_sem);

    while (priv->started) {
      ret = nxmutex_lock(&priv->cpu_lock);
      if (ret < 0) {
        break;
      }

      if (!priv->started) {
        nxmutex_unlock(&priv->cpu_lock);
        break;
      }

      ret = aic_audio_start_next_buffer(priv);
      if (ret < 0 && ret != -EAGAIN) {
        aic_audio_disable_pa(priv);
        hal_audio_abort(&priv->audio);
        aic_audio_complete_pending(priv);
      }

      nxmutex_unlock(&priv->cpu_lock);

      if (ret == -EAGAIN || ret < 0) {
        break;
      }
    }
  }

  return OK;
}

static void aic_audio_dma_callback(hal_audio_handle_t *haudio) {
  struct aic_audio_s *priv;
  FAR struct ap_buffer_s *apb;
  bool final;
  irqstate_t flags;

  priv = container_of(haudio, struct aic_audio_s, audio);

  if (!priv->started) {
    return;
  }

  flags = enter_critical_section();
  apb = priv->active;
  priv->active = NULL;
  leave_critical_section(flags);

  if (apb == NULL) {
    priv->xrun = true;
    auderr("audio tx xrun\n");
    return;
  }

  final = (apb->flags & AUDIO_APB_FINAL) != 0;

  aic_audio_complete_apb(priv, apb);

  if (final) {
    priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
    return;
    priv->started = false;
    if (aic_audio_use_cpu_tx()) {
      nxsem_post(&priv->cpu_sem);
      nxmutex_lock(&priv->cpu_lock);
      nxmutex_unlock(&priv->cpu_lock);
    }

    aic_audio_disable_pa(priv);
    hal_audio_abort(&priv->audio);
    hal_audio_deinit(&priv->audio);
    nxsig_usleep(50000);
  }
  audwarn("audio stop\n");
  flags = enter_critical_section();
  apb = priv->active;
  priv->active = NULL;
  leave_critical_section(flags);
  aic_audio_complete_apb(priv, apb);

  while (!dq_empty(&priv->pendq)) {
    flags = enter_critical_section();
    apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
    leave_critical_section(flags);
    aic_audio_complete_apb(priv, apb);
  }

  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
  return OK;
}
