    {
      printf("recorder: failed to initialize LVGL devices\n");
      lv_nuttx_deinit(&result);
      lv_deinit();
      pthread_mutex_destroy(&app.lock);
      return 1;
    }

  lv_indev_set_display(result.indev, result.disp);
  recorder_create_ui(&ui, &app);
