#else
  return AUDIO_OUTPUT_CHAN_PWM0_PWM1;
#endif
#elif defined(CONFIG_AIC_AUDIO_SPK_1)
  return AUDIO_OUTPUT_CHAN_PWM1;
#else
  return AUDIO_OUTPUT_CHAN_PWM0;
#endif
}

