    ret = aic_audio_start_transfer(
        priv, (const uint8_t *)apb->samp + apb->curbyte, bytes);
    if (ret < 0) {
      flags = enter_critical_section();
      priv->active = NULL;
      dq_addfirst(&apb->dq_entry, &priv->pendq);
      leave_critical_section(flags);
