static void aic_audio_complete_apb(struct aic_audio_s *priv,
                                   FAR struct ap_buffer_s *apb) {
  if (!apb) {
    return;
  }
  // csi_dcache_clean_range((uint32_t)apb->samp, apb->nbytes);
  apb->curbyte = 0;
