  if (dq_empty(&priv->pendq)) {
    auderr("audio start failed: no queued buffers\n");
    return -EAGAIN;
  }

  audwarn("audio start rate=%u channels=%u hw_channels=%u samplebits=%u "
          "period=%u fifo=%u\n",
