static uint32_t aic_audio_frame_bytes(struct aic_audio_s *priv) {
  uint32_t channels = priv->channels == 0 ? 2 : priv->channels;
  uint32_t samplebits = priv->samplebits == 0 ? 16 : priv->samplebits;

  return (samplebits / 8) * channels;
}

static int aic_audio_start_transfer(struct aic_audio_s *priv,
                                    const uint8_t *buffer, uint32_t bytes) {
  hal_status_e status;

  if (aic_audio_use_cpu_tx()) {
    uint32_t frame_bytes = aic_audio_frame_bytes(priv);
    uint32_t offset = 0;

    while (offset < bytes && priv->started) {
      uint32_t chunk = bytes - offset;

      if (chunk > 512) {
        chunk = 512;
      }

      chunk -= chunk % frame_bytes;
      status = hal_audio_transmit(&priv->audio, buffer + offset, chunk,
                                  AIC_AUDIO_CPU_TIMEOUT_MS);
      if (status != HAL_OK) {
        return aic_audio_hal_status_to_errno(status);
      }

      offset += chunk;
    }

    return priv->started ? OK : -ECANCELED;
  } else {
    if (priv->audio.state != AUDIO_STATE_READY) {
      return -EBUSY;
    }
    status = hal_audio_transmit_dma(&priv->audio, buffer, bytes);
  }

  return aic_audio_hal_status_to_errno(status);
}

static int aic_audio_pause_transfer(struct aic_audio_s *priv) {
  if (!aic_audio_use_cpu_tx()) {
    return aic_audio_hal_status_to_errno(hal_audio_dma_pause(&priv->audio));
  }

  return -ENOSYS;
}

static int aic_audio_resume_transfer(struct aic_audio_s *priv) {
  if (!aic_audio_use_cpu_tx()) {
    return aic_audio_hal_status_to_errno(hal_audio_dma_resume(&priv->audio));
  }

  return -ENOSYS;
}

static int aic_audio_start_next_buffer(struct aic_audio_s *priv) {
  irqstate_t flags;
  FAR struct ap_buffer_s *apb;
  uint32_t bytes;
  bool final;
  int ret;

  for (;;) {
    flags = enter_critical_section();
    if (priv->active != NULL) {
      leave_critical_section(flags);
      return OK;
    }

    apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
    priv->active = apb;
    if (apb == NULL) {
      priv->xrun = true;
    }
    leave_critical_section(flags);

    if (apb == NULL) {
      return -EAGAIN;
    }

    bytes = apb->nbytes - apb->curbyte;
    if (bytes == 0) {
      flags = enter_critical_section();
      priv->active = NULL;
      leave_critical_section(flags);
      if (apb->flags & AUDIO_APB_FINAL) {
        aic_audio_complete_apb(priv, apb);
        priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
        return OK;
      } else {
        aic_audio_complete_apb(priv, apb);
        continue;
      }
    }

    ret = aic_audio_start_transfer(
        priv, (const uint8_t *)apb->samp + apb->curbyte, bytes);
    if (ret < 0) {
      flags = enter_critical_section();
      priv->active = NULL;
      dq_addfirst(&apb->dq_entry, &priv->pendq);
      leave_critical_section(flags);
      return ret;
    }

    if (!aic_audio_use_cpu_tx()) {
      return OK;
    }

    final = (apb->flags & AUDIO_APB_FINAL) != 0;
    flags = enter_critical_section();
    priv->active = NULL;
    leave_critical_section(flags);
    aic_audio_complete_apb(priv, apb);

    if (final) {
      priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
      return OK;
    }

    return OK;

  }
}

static int aic_audio_cpu_thread(int argc, FAR char *argv[]) {
  struct aic_audio_s *priv = &g_aic_audio;
  int ret;

  UNUSED(argc);
  UNUSED(argv);

  for (;;) {
    nxsem_wait_uninterruptible(&priv->cpu_sem);

    while (priv->started) {
      ret = nxmutex_lock(&priv->cpu_lock);
      if (ret < 0) {
        break;
      }

      if (!priv->started) {
        nxmutex_unlock(&priv->cpu_lock);
        break;
      }

      ret = aic_audio_start_next_buffer(priv);
      if (ret < 0 && ret != -EAGAIN && ret != -ECANCELED) {
        aic_audio_disable_pa(priv);
        hal_audio_abort(&priv->audio);
        aic_audio_complete_pending(priv);
      }

      nxmutex_unlock(&priv->cpu_lock);

      if (ret == -EAGAIN || ret < 0) {
        break;
      }
    }
  }

  return OK;
}

